Lemma win_narrow : forall (M2 : mem) LB2 ps2, PML.win_ok M2 LB2 ps2 -> PML.ps_win ps2 = PML.ps_win ps -> PML.win_ok M2 LBo ps2.
Proof.
  intros M2 LB2 ps2 H Hw. pose proof HWIN as H0. unfold PML.win_ok in H, H0 |- *. rewrite Hw in H |- *. revert H H0.
  case (PML.ps_win ps); [intros [p e] | intros; exact I]. cbv beta iota.
  intros (ch2 & _ & _ & _ & D) (ch & Hin & H1 & H2 & _). exists ch. repeat split; assumption.
Qed.
