Lemma leaf_after : forall i c k ps1 j cj ci, is_leaf i c k ps1 (CC.TOther AFTERV) -> is_end i = false -> is_end j = true -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  SR.ps_pc ps1 = AFTERV -> CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true -> nth 10 (CA.ps_reglist ps1) (ELit 0) = Pb -> nth 11 (CA.ps_reglist ps1) (ELit 0) = Eb ->
  view_chk (SR.ps_cells ps1) = true -> PB.has (SR.ps_cells ps1) (KWord (SA Eb 0) 4 (ELit 0)) = true -> PB.has (SR.ps_cells ps1) (KWord (SA Vb 0) 8 (ELit PML.VT_VISITOR)) = true ->
  PB2.ptrans_chk GT.NF G.HDECL Eb 0 Pb 0 512 11 c ps1 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci -> is_vret i = true -> CH2.ci_csp ci = CSP ->
  forall g1 M0c, OKV M0c -> CC.leaf_ok (hl_segs L) G.CPS (AMB3XV g1 M0c) K PML.fp_ok i c ps1.
Proof.
  intros i c k ps1 j cj ci IL Hendi Hendj Hret Hcj Hpc Hbl H10 H11 Hview HhasE HhasV Hchk Hvr Hcsp g1 M0c OKV0.
  pose proof (CH2.blocks_eqb_eq _ _ Hbl) as Hbl'.
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof OBJS as (OP & OV & OS & OE & A1 & A2 & A3 & A4 & A5 & A6).
  pose proof (kit SPT.NUM) as (_ & _ & _ & _ & _ & _ & _ & _ & _ & NSL & _).
  refine (PB2.ptrans_leaf_ok L HI HIok LAY GT.NF E0 M0c model (LBr g1) sp G.HDECL W G.BLS (CredV g1) STKF SCRP NF32 U2 TP0 W_OK (CRS_OKV g1) WRS_OK IMG_OK G.CPS G.TAGS G.RETS K HKnil (XIv g1)
            (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV0) Eb 0 ltac:(vm_compute; reflexivity) E EADDR OE g HG Pb 0 ltac:(vm_compute; reflexivity) P PADDR V OBJJ WPAR_in _ _ _ _ _ _ _ _ (AFTERV_OKD mw)
            (fun pst M0 P0 ps2 H => pa_cap M0 P0 ps2 mw (proj1 H)) B (kx + PMX.kenc L g1) (bxu + PMES.benc L g1) 11 i c k ps1 j cj ci IL Hret Hcj Hpc Hchk _).
  intros E1 E' R' M1 M' model1 cr1 HagE' Hsr Hnx Hag HLF HRL HA XI1 HH1 HC1.
  pose proof HA as (_ & _ & HagE1 & _).
  assert (Hden1 : CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps) by (rewrite Hbl'; exact (kit SPT.den_BL0 E1 HagE1)).
  assert (Hden' : CH2.den E' (nth i G.BLS []) = PML.ps_blocks ps) by (rewrite Hbl'; exact (kit SPT.den_BL0 E' HagE')).
  pose proof XI1 as (HXj & HXI & HGF).
  unfold XIj in HXj. rewrite Hendi, Hvr in HXj.
  pose proof (below_frame i c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as HLOW.
  pose proof (xi0_low M1 M' HLOW HXj) as HX0'. pose proof HX0' as (_ & Hstk' & Hbuf').
  pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HK.
  pose proof (FRZ E' HagE') as (F2 & FP & FE & FV & F41 & F42 & F43 & F44 & F45 & F46 & F36 & F38 & F39 & F40 & FSE & FSC & FPE & FCE & F32 & F33 & F34).
  pose proof (gblocks_amb g1 M0c i E1 M' model1 HA) as GB.
  unfold view_chk in Hview. destruct (SPA.pview_w (SR.ps_cells ps1) Pb PE CE) as [pv|] eqn:HPV; [|discriminate Hview].
  apply andb_prop in Hview as [Hview Vsc]. apply andb_prop in Hview as [Hview Vse]. apply andb_prop in Hview as [Hview Vsb]. apply andb_prop in Hview as [Hview Vsz].
  apply andb_prop in Hview as [Hview Vdn]. apply andb_prop in Hview as [Hview Vmo]. apply andb_prop in Hview as [Hview Vns]. apply andb_prop in Hview as [Hview Vss].
  apply andb_prop in Hview as [Hview Vst]. apply andb_prop in Hview as [Hview Vwp]. apply andb_prop in Hview as [Vlv Vwe].
  apply expr_eqb_eq in Vsc, Vse, Vsb, Vsz, Vdn, Vmo, Vns, Vss, Vst, Vwp, Vlv, Vwe.
  unfold PML.obj_on_stack in OP, OV, OS, OE.
  assert (HdP' : L5.defined M' P 272).
  { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' model1 P 272 HA OKV0 (SPT.pa_def _ _ _ HPA)). left. lia. }
  destruct (SPA.parser_view_w E' M' (SR.ps_cells ps1) Pb PE CE pv P true (PML.ps_done ps) (PML.ps_stack ps) (PML.ps_scap ps) mw HK HPV FP ltac:(lia) ltac:(lia)
              ltac:(rewrite Vmo, PB2.uv_lit by lia; reflexivity) ltac:(rewrite Vdn; exact F46) ltac:(rewrite Vsb, F38; exact Hstk')
              ltac:(rewrite Vse, Vsb; change SEND0 with (APC.eadd (EVar 38) (EVar 39)); rewrite FSE, F38; reflexivity)
              ltac:(rewrite Vsc, Vsb; change SCEND0 with (APC.eadd (EVar 38) (EVar 40)); rewrite FSC, F38; reflexivity)
              NSL ltac:(rewrite Vwp; exact F32) ltac:(rewrite Vwe; exact F33) (kit SPT.mw_le) HdP') as (buf & HPAb & Hbl2 & _).
  rewrite Vst, Vss, Vns, Vlv, Vsb, F43, F44, F41, F38, FCE, FPE, PB2.uv_lit in HPAb by lia.
  rewrite Vsz, F36 in Hbl2.
  pose proof (pa_retext _ _ _ _ _ _ _ _ _ _ _ _ _ (PML.ps_buf ps) _ HPAb Hbuf' ltac:(lia)) as HPAc.
  assert (HPA' : PML.parser_at M' P (PML.ps_set_win ps mw)) by (unfold PML.ps_set_win; rewrite Hst, Hmore; exact HPAc).
  assert (HW' : PML.win_ok M' LBo ps).
  { apply (SPT.win_ok_tr M M' LBo ps ps eq_refl HWIN). intros ch p0 n0 Hch Hp1 Hp2 Hd.
    apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' model1 p0 n0 HA OKV0 Hd). right. exists ch. split; [exact Hch | lia]. }
  assert (HVIS' : PML.vis_at M' V).
  { pose proof (PB.has_ok E' M' _ _ HK HhasV) as KV.
    assert (Hest : estart E' (SA Vb 0) = V) by (unfold estart; cbn [a_base a_off]; change (bv_unsigned (edenot E' Vb)) with (uv E' Vb); rewrite FV; lia).
    pose proof (PB2.kword64_elim E' M' _ _ V KV Hest) as Q.
    rewrite PB2.uv_lit in Q by (split; [apply Z.leb_le | apply Z.ltb_lt]; vm_compute; reflexivity). exact Q. }
  assert (HEC' : PML.ec_at M' E 0).
  { pose proof (PB.has_ok E' M' _ _ HK HhasE) as KE.
    assert (Hest : estart E' (SA Eb 0) = E) by (unfold estart; cbn [a_base a_off]; change (bv_unsigned (edenot E' Eb)) with (uv E' Eb); rewrite FE; lia).
    pose proof (PB2.kword32_elim E' M' _ _ E KE Hest) as Q. rewrite PB2.uv_lit in Q by lia.
    split; [exact Q|]. split; [|left; reflexivity].
    apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' model1 E 16 HA OKV0 (proj1 (proj2 HEC))). left. lia. }
  exists ps. split; [exact Hden'|]. split.
  { unfold PB2.ptrans_pre.
  split; [split; [unfold PML.a0; exact (reg_arg E' R' _ 10%bv 10 Pb P HRL eq_refl eq_refl H10 FP) | split; [unfold PML.a1; exact (reg_arg E' R' _ 11%bv 11 Eb E HRL eq_refl eq_refl H11 FE) | split; [exact Hmore | exact Hst]]]|].
  split; [exact HPA'|]. split; [exact HWF|].
  split; [exact (win_widen M' LBo (LBr g1) ps (fun b Hb => in_or_app _ _ _ (or_introl Hb)) HW')|].
  split; [exact HBB|]. split; [exact HVIS'|]. split; [exact HEC'|]. split; [exact (xi0_ls M' HX0')|].
  apply (proj1 (cred_pc g1 i E1 cr1 ps Hden1 (proj2 WFM))). exact HC1. }
  intros R2 M2 cr2 ps2 code g' E2 HPOST Hag2 Hcode Hden2 HP2.
  destruct HPOST as ((HPA2 & Hw2) & HWF2 & HWIN2 & HBB2 & HEC2 & Hmore2 & HLS2 & Hg' & HPC2 & (HAV & Hdone2)).
  pose proof (xinv_leaf g1 i c E1 M1 M' E' R' ps1 Hc GB XI1 HagE' HLF) as HXI'.
  split.
  - split; [|split].
    + unfold XIj. rewrite Hendj. exists ps2, code, g'.
      split; [split; [exact HPA2 | exact Hw2]|]. split; [exact HWF2|]. split; [exact (win_narrow M2 _ ps2 HWIN2 Hw2)|]. split; [exact HBB2|]. split; [exact HEC2|].
      split; [exact Hmore2|]. split; [exact HLS2|]. split; [exact Hg'|]. split; [split; [exact HAV | exact Hdone2] | exact Hden2].
    + assert (CSPn : CSP < 0) by (apply Z.ltb_lt; vm_compute; reflexivity).
      assert (CSPb : 512 - CSP <= SCRC) by (rewrite SCRCV; apply Z.leb_le; vm_compute; reflexivity).
      apply (kitx SPTX.inv_hpres M' M2 g1 (LBr g1) (sp + CH2.ci_csp ci) 512 (PML.W_par P E) HP2); [intros b Hb; apply in_or_app; right; exact Hb | rewrite Hcsp; lia | rewrite Hcsp; lia | | exact GB | exact HXI'].
      unfold SPTX.wc_ok. intros w Hw. unfold PML.W_par in Hw. unfold PML.apart in A1, A2, A3, A4, A5, A6. unfold PMES.ENC_SIZE in *.
      destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI; rewrite ?(PmLayout.ly_img_lo L LAY), ?(PmLayout.ly_img_hi L LAY);
        (split; [lia | split; [lia | first [left; lia | right; lia]]]).
    + unfold GF in HGF |- *. rewrite Hendi, Hvr in HGF. rewrite Hendj. cbn [orb] in HGF |- *. exact HGF.
  - apply (proj2 (cred_pc g1 j E2 cr2 ps2 Hden2 (proj1 (proj2 (proj2 (proj2 HWF2)))))). exact HPC2.
Qed.

(* [comment removed for export] *)
Lemma leaf_fb : forall c E' (M1 M' : mem), forallb stack_reg_eqb (CC.cp_F c) = true -> env_agree GT.NF E0 E' ->
  (forall a : word, SGP.outside E' (CC.cp_F c) a -> M' a = M1 a) -> L5.frame_but [(sp - CH.hd_scr G.HDECL, CH.hd_scr G.HDECL)] M1 M'.
Proof.
  intros c E' M1 M' Hs Hag HF x Hx. apply HF. unfold SGP.outside. apply Forall_forall. intros [[b lo] len] Hr.
  pose proof (proj1 (forallb_forall _ _) Hs _ Hr) as Q. unfold stack_reg_eqb in Q. cbv beta iota in Q.
  apply andb_prop in Q as [Q Q3]. apply andb_prop in Q as [Q1 Q2]. apply expr_eqb_eq in Q1, Q3. apply Z.eqb_eq in Q2. subst b lo len.
  assert (VL : APC.expr_vars_lt GT.NF (EVar 2) = true) by (vm_compute; reflexivity).
  rewrite (PB.estart_agree GT.NF E0 E' (EVar 2) (- SCR) Hag VL). unfold estart, elenZ. cbn [a_base a_off edenot].
  rewrite U2. specialize (Hx _ (or_introl eq_refl)). unfold L5.in_rng in Hx. cbn [fst snd] in Hx. pose proof SCRV as SV. unfold SCR in *.
  assert (Q : bv_unsigned (Z_to_bv 64 (CH.hd_scr G.HDECL)) = CH.hd_scr G.HDECL) by (rewrite SV; reflexivity).
  rewrite Q. lia.
Qed.
Lemma exit_end : forall i c k ps1 pc, is_leaf i c k ps1 (CC.TOther pc) -> is_end i = true -> PB.exit_base_chk GT.NF pc c ps1 = true -> In pc GT.ENDS -> forallb stack_reg_eqb (CC.cp_F c) = true ->
  forall g1 M0c, OKV M0c -> CC.leaf_ok (hl_segs L) G.CPS (AMB3XV g1 M0c) K PML.fp_ok i c ps1.
Proof.
  intros i c k ps1 pc IL Hend Hchk Hin Hstk g1 M0c OKV0.
  intros fx' E1 R1 M1 m1 E' R' M' HAt [HAmb HX] HFP Hag HLF _.
  pose proof Hentry as (Hra & Hraok & _ & _ & _).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof SCRV as SV. pose proof SCRCV as SCV.
  pose proof (kitx SPTX.okV_defc M0c OKV0) as DEFC.
  assert (EV : forall x : reg, ev E0 (ridx x) = getr R x) by (intros x; first [apply CL5.ev_reg | exact (SPT.EV0 mw B ps R line0 pos0 XV SPT.noeb x)]).
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (gblocks_amb g1 M0c i E1 M1 m1 HAmb) as GB.
  apply (PB.exit_ret L HI HIok LAY GT.NF E0 M0c model (LBr g1) sp G.HDECL W G.BLS (CredV g1) STKF SCRP NF32 U2 W_OK WRS_OK G.CPS G.TAGS K (XIv g1)
           (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV0) (fun _ => 0) (fun _ => 0)
           SCRC (proj2 S7) S6 DEFC R EV r Hra Hraok heap_ok3 pc i c k ps1 pc (rets pc Hin) IL Hchk fx' E1 R1 M1 m1 E' R' M' HAt HAmb Hag HLF).
  intros HRP HP HA' HagE'.
  destruct HA' as (Hmo1 & Hbv1 & HagE1 & (cr1 & HH1 & HC1) & _ & _).
  pose proof HX as (HXj & HXI & HGF). pose proof HGF as HGF0.
  unfold XIj in HXj. rewrite Hend in HXj.
  destruct HXj as (ps2 & code & g' & (HPA1 & Hwin2) & HWF2 & HWIN1 & HBB2 & HEC1 & Hmore2 & HLS1 & Hg' & (HAV & Hdone) & Hden).
  unfold GF in HGF. rewrite Hend in HGF. cbn [orb] in HGF. destruct HGF as (Hes & Hpay).
  pose proof (CC.lf_grows _ _ _ _ _ _ _ HLF) as GR.
  pose proof (leaf_fb c E' M1 M' Hstk HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as FB.
  assert (OUT : forall a n, 0 <= a -> a + n <= 2 ^ 64 -> (a + n <= sp - CH.hd_scr G.HDECL \/ sp <= a) -> PB2.out [(sp - CH.hd_scr G.HDECL, CH.hd_scr G.HDECL)] a n).
  { intros a n A0 A1 A2. split; [exact A0|]. split; [exact A1|]. intros q Hq r0 Hr0 Hin0. destruct Hr0 as [<-|[]]. unfold L5.in_rng in Hin0. cbn [fst snd] in Hin0. lia. }
  pose proof OBJS as ((OP1 & OP2 & _) & _ & _ & (OE1 & OE2 & _) & _).
  destruct (hio_wf L SCFG HI HIok _ _ _ _ HH1) as (Hwf & _).
  assert (Hb1 : In (PML.ps_bptr ps2, PML.ps_bcap ps2) (CH2.cur (LBr g1) G.BLS i E1)) by (unfold CH2.cur; rewrite Hden; apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto).
  assert (Hb2 : In (PML.ps_sb ps2, PML.ps_scap ps2) (CH2.cur (LBr g1) G.BLS i E1)) by (unfold CH2.cur; rewrite Hden; apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto).
  destruct (Hwf _ Hb1) as ((B1a & _ & _ & B1d & B1e) & _). destruct (Hwf _ Hb2) as ((B2a & _ & _ & B2d & B2e) & _). cbn [fst snd] in B1a, B1d, B1e, B2a, B2d, B2e.
  assert (HPA2 : PML.parser_at M' P (PML.ps_set_win ps2 mw)).
  { apply (PB2.parser_at_fr _ M1 M' FB GR P (PML.ps_set_win ps2 mw)); cbn [PML.ps_bptr PML.ps_bcap PML.ps_sb PML.ps_scap PML.ps_set_win]; [apply OUT; lia | apply OUT; lia | apply OUT; lia | exact HPA1]. }
  assert (HEC2 : PML.ec_at M' E code) by (apply (PB2.ec_at_fr _ M1 M' FB GR E code); [apply OUT; lia | exact HEC1]).
  assert (HWIN2 : PML.win_ok M' LBo ps2) by exact (PB2.win_ok_fr M1 M' GR LBo ps2 HWIN1).
  assert (Hg0 : g' <> PML.LS0) by (destruct Hg' as [-> | (-> & _)]; [exact HG | discriminate]).
  assert (HLS2 : PML.ls_ok g' M') by (apply (PB2.ls_ok_fr _ M1 M' FB g' Hg0); [apply OUT; lia | exact HLS1]).
  pose proof (xinv_leaf g1 i c E1 M1 M' E' R' ps1 Hc GB HX HagE' HLF) as (HINV2 & HLIT2).
  pose proof (kitx SPTX.okV_hpres g1 M0c M' OKV0 HP) as HP2.
  assert (HWB2 : PMW.win_bytes M' ps2 ww).
  { apply (SPTW.win_bytes_kept L HI HIok LAY (PML.ps_blocks ps ++ LBo ++ gB eg) cr M M' (m_vmmaps model) LBo sp SCRC W ps ps2 ww HH);
      [intros b0 Hb0; apply in_or_app; right; apply in_or_app; left; exact Hb0 | exact (proj1 HP2) | exact S6 | lia | lia | exact (SPTW.wparx_split L LAY sp P V E S2 OBJS) | exact HWIN | exact HWB | exact Hwin2]. }
  destruct HAV as (Hc0 & Hm2 & Hst2 & Hstk2 & Hlv2 & Hw2).
  apply (Hcont fx' R' M' m1 (PML.ps_blocks ps2 ++ LBo ++ gB g1) cr1 LBo W HFP); [| exact HRP | exact HP2 | exact Hbv1 | unfold CH2.cur, CH2V.LBr in HH1; rewrite Hden in HH1; exact HH1].
  exists ps2, code, g', g1.
  split; [split; [exact HPA2 | exact Hwin2]|].
  split; [exact HWF2|]. split; [exact HWIN2|]. split; [exact HBB2|]. split; [exact HEC2|]. split; [exact Hmore2|]. split; [exact HLS2|]. split; [exact Hg'|].
  split; [exact HINV2|]. split; [exact HLIT2|].
  split.
  { intros _. split; [rewrite (gf_depth i g1 HGF0), Hlv2; exact (proj1 HSYNC)|].
    intros Hm Hk. rewrite Hlv2. apply (proj2 HSYNC Hmore). destruct Hk as [Hk|Hk].
    - exfalso. rewrite Hst2 in Hk. revert Hk. destruct (PML.ps_level ps =? 0); intros Hk; vm_compute in Hk; lia.
    - right. rewrite <- Hstk2. exact Hk. }
  split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
  split; [apply (proj1 (cred_pc g1 i E1 cr1 ps2 Hden (proj1 (proj2 (proj2 (proj2 HWF2)))))); exact HC1|].
  split; [left; split; [exact Hc0|]; split; [exact Hm2|]; split; [exact Hst2|]; split; [exact Hstk2|]; split; [exact Hlv2 | exact Hw2]|].
  exact (SPTW.w3_end_number false cw M' P ps ps2 ww eg g1 code HRM HWF Hmore Hst (conj Hc0 (conj Hm2 (conj Hst2 (conj Hstk2 (conj Hlv2 Hw2))))) Hdone Hes Hpay HWB2).
Qed.

