Lemma vis_ev_ok : forall ev, In ev [EvDbl; EvStr 3 (PML.ps_buf ps)] ->
  (forall es, ev_ind es ev = fst (pre_scalar es) /\ estep es ev = bump (snd (pre_scalar es))) /\
  (forall pay, pay_ok ev pay -> 0 <= pay <= 28 + Z.of_nat (length (PML.ps_buf ps))) /\
  ev_guard (g_es eg) ev /\ eroomU eg ev.
Proof.
  intros ev Hin. cbn [In] in Hin.
  destruct Hin as [<-|[<-|[]]].
  - split; [intros es; split; [cbn [ev_ind quotes]; lia | reflexivity]|].
    split; [intros pay Hp; cbn [pay_ok] in Hp; lia|].
    split; [exact I|].
    apply (SPXWU.room_end_number true cw (PML.ps_buf ps) eg EvDbl HROOM); [reflexivity | cbn [pay_hi]; lia].
  - split; [intros es; split; [cbn [ev_ind quotes Z.eqb Pos.eqb orb]; lia | reflexivity]|].
    split; [intros pay Hp; cbn [pay_ok Z.eqb Pos.eqb orb] in Hp; unfold PMES.len in Hp; lia|].
    split; [exact I|].
    exact (SPXWU.room_end_number_raw true cw (PML.ps_buf ps) eg 3 HROOM (or_intror eq_refl)).
Qed.
Lemma xi0_keep : forall (M' M2 : mem) LB sp1 scr, (forall b, In b (PML.ps_blocks ps) -> In b LB) ->
  L5C.hpres L LB sp1 scr (W_enc V S2) M' M2 -> XI0 M' -> XI0 M2.
Proof.
  intros M' M2 LB sp1 scr HLB HP (HF' & HS' & HB').
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. pose proof (PmLayout.ly_errno L LAY) as LER.
  pose proof OBJS as ((OP1 & OP2 & _) & (OV1 & OV2 & _) & (OS1 & OS2 & _) & (OE1 & OE2 & _) & _).
  pose proof (kit SPT.NUM) as ((BR0 & BR1 & BR2 & BR3 & BR4) & (BS0 & BS1 & BS2 & BS3 & BS4) & _ & _ & _ & _ & _ & BLN & _ & SL2 & _).
  rewrite ILO, IHI in BR1, BS1.
  unfold XI0. change sb with (PML.ps_sb ps). change bptr with (PML.ps_bptr ps).
  split; [|split].
  - intros a Ha. rewrite <- (HF' a Ha). apply (L5C.hpres_kept _ _ _ _ _ _ _ a HP).
    pose proof (foot_low a Ha) as Fa.
    split; [lia|]. split; [|split].
    + right. right. rewrite ILO, IHI. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. split; [lia|]. intros X. pose proof (PmLayout.ly_static L LAY a X). lia.
    + unfold in_errno. rewrite LER. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. lia.
    + intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha.
      destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH in *; lia.
  - apply (L5C.bytes_at_agree RSEGS M' M2 (PML.ps_sb ps) (PML.ps_stack ps)); [| lia | lia | exact HS'].
    intros q Hq. apply (L5C.hpres_kept _ _ _ _ _ _ _ q HP).
    split; [lia|]. split; [|split].
    + left. exists (PML.ps_sb ps, PML.ps_scap ps). split; [apply HLB; unfold PML.ps_blocks; cbn [In]; auto | cbn [fst snd]; lia].
    + unfold in_errno. rewrite LER. lia.
    + intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw.
      destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH, PMES.ENC_SIZE in *; lia.
  - apply (L5C.bytes_at_agree RSEGS M' M2 (PML.ps_bptr ps) (PML.ps_buf ps)); [| lia | lia | exact HB'].
    intros q Hq. apply (L5C.hpres_kept _ _ _ _ _ _ _ q HP).
    split; [lia|]. split; [|split].
    + left. exists (PML.ps_bptr ps, PML.ps_bcap ps). split; [apply HLB; unfold PML.ps_blocks; cbn [In]; auto | cbn [fst snd]; lia].
    + unfold in_errno. rewrite LER. lia.
    + intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw.
      destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH, PMES.ENC_SIZE in *; lia.
Qed.
Lemma vis_common : forall ev g1 M0c i c k ps1 pc, In ev [EvDbl; EvStr 3 (PML.ps_buf ps)] -> is_leaf i c k ps1 (CC.TOther pc) -> is_end i = false -> is_vret i = false ->
  CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true ->
  forall Ec (M1 : mem) model1 E' R' (M' : mem) cr1, HAMBV g1 M0c i Ec M1 model1 -> XIv g1 i Ec M1 -> env_agree GT.NF E0 E' ->
    CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> CredV g1 i Ec cr1 ->
    g1 = eg /\ CH2.den E' (nth i G.BLS []) = PML.ps_blocks ps /\
    L5.bytes_at RSEGS M' (PML.ps_bptr ps) (PML.ps_buf ps) /\ L5.defined M' (PML.ps_bptr ps) (Z.of_nat (length (PML.ps_buf ps))) /\
    enc_inv M' V S2 g1 /\ ev_guard (g_es g1) ev /\ eroomU g1 ev /\ PML.img_ro M' /\ PML.lits_ok M' /\
    PMES.ecreditU L cr1 g1 (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps).
Proof.
  intros ev g1 M0c i c k ps1 pc Hev IL Hendi Hvri HBLi Ec M1 model1 E' R' M' cr1 HAmb HX HagE' HLF HC.
  pose proof IL as (tags & Hc & _).
  pose proof (gblocks_amb g1 M0c i Ec M1 model1 HAmb) as GB.
  pose proof (xinv_leaf g1 i c Ec M1 M' E' R' ps1 Hc GB HX HagE' HLF) as (HINV' & HLIT').
  pose proof (vis_ev_ok ev Hev) as (_ & _ & HGD & HRM1).
  destruct HX as (HXj & _ & HGF).
  unfold GF in HGF. rewrite Hendi, Hvri in HGF. cbn [orb] in HGF. subst g1.
  pose proof (xi_low i Ec M1 Hendi Hvri HXj) as HXL.
  pose proof (below_frame i c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as HLOW.
  pose proof (xlow_tr0 M1 M' HLOW HXL) as HXL'.
  assert (HagE : env_agree GT.NF E0 Ec) by exact (amb_agree eg M0c i Ec M1 model1 HAmb).
  assert (Hden : CH2.den Ec (nth i G.BLS []) = PML.ps_blocks ps) by (rewrite (CH2.blocks_eqb_eq _ _ HBLi); exact (kit SPT.den_BL0 Ec HagE)).
  assert (Hden' : CH2.den E' (nth i G.BLS []) = PML.ps_blocks ps) by (rewrite (CH2.blocks_eqb_eq _ _ HBLi); exact (kit SPT.den_BL0 E' HagE')).
  pose proof (kit SPT.NUM) as ((BR0 & BR1 & BR2 & BR3 & BR4) & _ & DB & _ & _ & _ & _ & BLN & _).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. rewrite ILO, IHI in BR1.
  split; [reflexivity|]. split; [exact Hden'|].
  split.
  { apply (xlow_bytes M' (PML.ps_bptr ps) (PML.ps_bcap ps) (PML.ps_buf ps) HXL'); [lia | lia | lia | lia | exact (proj1 entry_bytes)]. }
  split.
  { intros q Hq. rewrite (HXL' (PML.ps_bptr ps + q)); [apply DB; lia | lia | unfold in_errno; rewrite errno_v; lia]. }
  split; [exact HINV'|]. split; [exact HGD|]. split; [exact HRM1|].
  destruct (xlow_ls M' HXL') as (HIMG & _).
  split; [exact HIMG|]. split; [exact HLIT'|].
  pose proof (proj1 (cred_pc eg i Ec cr1 ps Hden (proj2 WFM)) HC) as HPC1. rewrite PMX.kenc_eq in HPC1.
  pose proof WFM as (_ & HS). unfold scap in HS. cbn [In] in HS.
  exact (SPXWU.ecredit_of_pxU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr1 ps eg kx bxu HPC1 Hkx Hbxu0 ltac:(lia)).
Qed.
Lemma vis_site_num : forall g1 M0c i c k ps1 cj ci pc, is_leaf i c k ps1 (CC.TOther pc) -> is_end i = false -> is_vret i = false ->
  CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true ->
  forall Ec R1 (M1 : mem) model1 E' R' (M' : mem) cr1, CC.At (hl_segs L) c Ec R1 M1 -> HAMBV g1 M0c i Ec M1 model1 -> XIv g1 i Ec M1 -> env_agree (CC.cp_nx c) Ec E' ->
    CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    CH2.common_facts_x L HI GT.NF E0 M0c model (CH2V.LBr LBo eghost VBX.gB g1) sp G.HDECL W G.BLS (CredV g1) VBX.VIS_SCR 0 c ps1 cj ci i Ec E' R' M' model1 ->
    hi_heap HI ((CH2.den E' (nth i G.BLS []) ++ LBo) ++ g_lbv g1) cr1 M' (m_vmmaps model1) -> CredV g1 i Ec cr1 ->
    True /\ enc_inv M' V S2 g1 /\ ev_guard (g_es g1) EvDbl /\ eroomU g1 EvDbl /\ PML.img_ro M' /\ PML.lits_ok M' /\
    PMES.ecreditU L cr1 g1 (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps).
Proof.
  intros g1 M0c i c k ps1 cj ci pc IL Hendi Hvri HBLi Ec R1 M1 model1 E' R' M' cr1 _ HAmb HX _ HLF CF _ HC.
  pose proof CF as [_ _ _ _ _ _ _ _ _ HagE' _ _].
  destruct (vis_common EvDbl g1 M0c i c k ps1 pc (or_introl eq_refl) IL Hendi Hvri HBLi Ec M1 model1 E' R' M' cr1 HAmb HX HagE' HLF HC) as (_ & _ & _ & _ & H).
  split; [exact I | exact H].
Qed.
Lemma vis_site_str : forall g1 M0c i c k ps1 cj ci, is_leaf i c k ps1 (CC.TOther VSTR) -> is_end i = false -> is_vret i = false ->
  CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true ->
  expr_eqb (nth 11 (CA.ps_reglist ps1) (ELit 0)) (APC.eaddz (EVar 2) SVOFF) = true -> expr_eqb (nth 12 (CA.ps_reglist ps1) (ELit 0)) (ELit 3) = true ->
  PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) SVOFF) 8 PE) = true -> PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) (SVOFF + 8)) 8 (EVar 36)) = true ->
  CH2.ci_csp ci <= SVOFF ->
  forall Ec R1 (M1 : mem) model1 E' R' (M' : mem) cr1, CC.At (hl_segs L) c Ec R1 M1 -> HAMBV g1 M0c i Ec M1 model1 -> XIv g1 i Ec M1 -> env_agree (CC.cp_nx c) Ec E' ->
    CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    CH2.common_facts_x L HI GT.NF E0 M0c model (CH2V.LBr LBo eghost VBX.gB g1) sp G.HDECL W G.BLS (CredV g1) VBX.VIS_SCR 0 c ps1 cj ci i Ec E' R' M' model1 ->
    hi_heap HI ((CH2.den E' (nth i G.BLS []) ++ LBo) ++ g_lbv g1) cr1 M' (m_vmmaps model1) -> CredV g1 i Ec cr1 ->
    (exists sv, PML.a1 R' sv /\ PML.a2 R' 3 /\ sv_argU L (CH2.den E' (nth i G.BLS []) ++ LBo) M' (sp + CH2.ci_csp ci) V S2 sv (PML.ps_buf ps)) /\
    enc_inv M' V S2 g1 /\ ev_guard (g_es g1) (EvStr 3 (PML.ps_buf ps)) /\ eroomU g1 (EvStr 3 (PML.ps_buf ps)) /\ PML.img_ro M' /\ PML.lits_ok M' /\
    PMES.ecreditU L cr1 g1 (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps).
Proof.
  intros g1 M0c i c k ps1 cj ci IL Hendi Hvri HBLi H11 H12 HK1 HK2 Hcsp Ec R1 M1 model1 E' R' M' cr1 _ HAmb HX _ HLF CF _ HC.
  pose proof CF as [_ HRL HRLeq _ _ _ _ _ _ HagE' _ _].
  rewrite HRLeq in HRL.
  destruct (vis_common (EvStr 3 (PML.ps_buf ps)) g1 M0c i c k ps1 VSTR (or_intror (or_introl eq_refl)) IL Hendi Hvri HBLi Ec M1 model1 E' R' M' cr1 HAmb HX HagE' HLF HC)
    as (_ & Hden' & HBY & HDF & H).
  split; [|exact H].
  apply expr_eqb_eq in H11, H12.
  pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HKN.
  pose proof (est_sv E' HagE') as (ES1 & ES2 & ES3).
  pose proof (FRZ E' HagE') as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & F36 & _ & _ & _ & _ & _ & FPE & _).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (kit SPT.NUM) as ((BR0 & _ & _ & _ & BR4) & _ & _ & _ & _ & _ & _ & BLN & _).
  pose proof OBJS as (_ & (OV1 & OV2 & _) & (OS1 & OS2 & _) & _).
  exists (sp + SVOFF). split; [|split].
  - unfold PML.a1. exact (reg_arg E' R' _ 11%bv 11 _ (sp + SVOFF) HRL eq_refl eq_refl H11 ES3).
  - unfold PML.a2. exact (reg_arg E' R' _ 12%bv 12 _ 3 HRL eq_refl eq_refl H12 ltac:(rewrite PB2.uv_lit by lia; reflexivity)).
  - exists (PML.ps_bptr ps).
    pose proof (PB2.kword64_elim E' M' _ _ (sp + SVOFF) (PB.has_ok E' M' _ _ HKN HK1) ES1) as Q1. rewrite FPE in Q1.
    pose proof (PB2.kword64_elim E' M' _ _ (sp + SVOFF + 8) (PB.has_ok E' M' _ _ HKN HK2) ES2) as Q2. rewrite F36 in Q2.
    unfold PML.u64. split; [exact Q1|]. split; [lia|]. split; [exact Q2|]. split; [exact HBY|]. split; [exact HDF|].
    split.
    { right. exists (PML.ps_bptr ps, PML.ps_bcap ps). split; [rewrite Hden'; apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto | cbn [fst snd]; unfold PMES.len; lia]. }
    assert (HM : (sp + SVOFF) mod 8 = 0).
    { unfold SVOFF. rewrite (Z.div_mod sp 16) by lia. rewrite S1. replace (16 * (sp / 16) + 0 + -48) with ((2 * (sp / 16) - 6) * 8) by lia. apply Z.mod_mul. lia. }
    unfold PML.apart, PML.obj_on_stack, PMES.ENC_SIZE. unfold SVOFF in Hcsp |- *.
    split; [left; lia|]. split; [left; lia|]. split; [lia|]. split; [lia | exact HM].
Qed.
Lemma vis_ret : forall ev i c ps1 ci j g1, In ev [EvDbl; EvStr 3 (PML.ps_buf ps)] -> nth_error G.CPS i = Some c -> is_end i = false -> is_vret i = false ->
  CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true -> is_vret j = true -> is_end j = false -> CH2.blocks_eqb (nth j G.BLS []) SPT.BL0 = true ->
  forall Ec E' R' (M1 M' : mem) E2 (M2 : mem) g' cr', XIv g1 i Ec M1 -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) Ec E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    env_agree (CH2.ci_nx ci) E' E2 -> (CC.cp_nx c <= CH2.ci_nx ci)%nat ->
    L5C.hpres L (CH2.den E' (nth i G.BLS []) ++ LBo) (sp + CH2.ci_csp ci) VBX.VIS_SCR (W_enc V S2) M' M2 ->
    hl_sptop L - 2 ^ 23 + VBX.VIS_SCR <= sp + CH2.ci_csp ci -> sp + CH2.ci_csp ci <= sp ->
    VBXU.vret V S2 g1 ev Ec g' M2 -> PMES.ecreditU L cr' g' (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps) ->
    XIv g' j E2 M2 /\ CredV g' j E2 cr'.
Proof.
  intros ev i c ps1 ci j g1 Hev Hc Hendi Hvri HBLi Hvrj Hendj HBLj Ec E' R' M1 M' E2 M2 g' cr' HX HagE' Hag HLF Hag2 Hnx HP _ _ HR HCR.
  pose proof (vis_ev_ok ev Hev) as (HEV & HPAY & _ & _).
  destruct HX as (HXj & _ & HGF).
  unfold GF in HGF. rewrite Hendi, Hvri in HGF. cbn [orb] in HGF. subst g1.
  pose proof (xi_low i Ec M1 Hendi Hvri HXj) as HXL.
  pose proof (below_frame i c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as HLOW.
  pose proof (xi0_of_xlow M' (xlow_tr0 M1 M' HLOW HXL)) as HX0'.
  pose proof (CC.cps_all_sound _ _ nf_all i c Hc) as NFc. cbv beta in NFc. apply Nat.leb_le in NFc.
  assert (NF2 : (GT.NF <= CH2.ci_nx ci)%nat) by lia.
  assert (HagE2 : env_agree GT.NF E0 E2) by (apply (CC.env_agree_trans _ E0 E' E2 HagE'); exact (CC.env_agree_le _ _ _ _ Hag2 NF2)).
  assert (Hden' : CH2.den E' (nth i G.BLS []) = PML.ps_blocks ps) by (rewrite (CH2.blocks_eqb_eq _ _ HBLi); exact (kit SPT.den_BL0 E' HagE')).
  assert (Hden2 : CH2.den E2 (nth j G.BLS []) = PML.ps_blocks ps) by (rewrite (CH2.blocks_eqb_eq _ _ HBLj); exact (kit SPT.den_BL0 E2 HagE2)).
  assert (HLB : forall b, In b (PML.ps_blocks ps) -> In b (CH2.den E' (nth i G.BLS []) ++ LBo)) by (intros b Hb; rewrite Hden'; apply in_or_app; left; exact Hb).
  destruct HR as (HINV2 & HLIT2 & Hes & pay & Hpay & Hlen).
  split.
  - split; [|split].
    + unfold XIj. rewrite Hendj, Hvrj. exact (xi0_keep M' M2 _ _ _ HLB HP HX0').
    + exact (conj HINV2 HLIT2).
    + unfold GF. rewrite Hendj, Hvrj. cbn [orb].
      destruct (HEV (g_es eg)) as (HI1 & HS1).
      split; [rewrite Hes; exact HS1|]. exists pay. split; [exact (HPAY pay Hpay)|]. rewrite Hlen, HI1. reflexivity.
  - apply (proj2 (cred_pc g' j E2 cr' ps Hden2 (proj2 WFM))). rewrite PMX.kenc_eq.
    apply (SPXWU.px_of_ecreditU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr cr' ps eg g' kx bxu); [| exact Hkx | exact Hbxu0 | exact HCR].
    rewrite <- PMX.kenc_eq, <- Hbxu. exact HPC.
Qed.
Lemma leaf_vis : forall g1 M0c, OKV M0c -> forall (pc : Z) i c k ps1 j cj ci, is_leaf i c k ps1 (CC.TOther pc) -> is_vis pc = true -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  SR.ps_pc ps1 = pc -> is_end i = false -> is_vret i = false -> CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true -> is_vret j = true -> is_end j = false -> CH2.blocks_eqb (nth j G.BLS []) SPT.BL0 = true ->
  (pc = VSTR -> expr_eqb (nth 11 (CA.ps_reglist ps1) (ELit 0)) (APC.eaddz (EVar 2) SVOFF) = true /\ expr_eqb (nth 12 (CA.ps_reglist ps1) (ELit 0)) (ELit 3) = true /\
                PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) SVOFF) 8 PE) = true /\ PB.has (SR.ps_cells ps1) (KWord (SA (EVar 2) (SVOFF + 8)) 8 (EVar 36)) = true) ->
  VBX.vis_chk GT.NF G.HDECL Vb c ps1 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci -> CH2.ci_csp ci <= SVOFF ->
  CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv G.CPS K PML.fp_ok g1 M0c i c ps1.
Proof.
  intros g1 M0c OKV0 pc i c k ps1 j cj ci IL Hvis Hret Hcj Hpc Hendi Hvri HBLi Hvrj Hendj HBLj HSTR Hchk Hcsp.
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (kit SPT.UU) as (_ & _ & _ & UV).
  pose proof OBJS as (_ & OV' & OS' & _ & _ & _ & _ & AVS & _).
  assert (OBE : objs_enc L sp V S2) by exact (conj OV' (conj OS' AVS)).
  pose proof (CH2.leaves_all_sound _ _ _ vis_case_ok _ _ _ _ _ IL) as Q. unfold vis_case_chk in Q. rewrite Hvis in Q.
  apply Bool.orb_true_iff in Q as [Hd | Hs].
  - apply Z.eqb_eq in Hd. rewrite Hd in IL, Hpc.
    exact (VBXU.vis_leaf_okU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv STKF SCRP NF32 U2 TP0 W_OK CRS_OK WRS_OK IMG_OK
             G.CPS G.TAGS G.RETS K HKnil DEF0 V S2 W_ENC Vb ltac:(vm_compute; reflexivity) UV S2LT (kitx SPTX.FRZS2 E0 (CC.env_agree_refl _ _)) ltac:(vm_compute; reflexivity)
             VDBL EvDbl (fun _ _ _ => True) (fun _ => kx + PML.kleft ps * hl_k_per_malloc L) (fun _ => bxu + PMX.pbytes L ps)
             i c k ps1 j cj ci g1 M0c VDOUBLE OBE OKV0 IL Hret Hcj Hpc Hchk
             (vis_site_num g1 M0c i c k ps1 cj ci VDBL IL Hendi Hvri HBLi)
             (vis_ret EvDbl i c ps1 ci j g1 (or_introl eq_refl) Hc Hendi Hvri HBLi Hvrj Hendj HBLj)).
  - apply Z.eqb_eq in Hs. rewrite Hs in IL, Hpc, HSTR. destruct (HSTR eq_refl) as (H11 & H12 & HK1 & HK2).
    exact (VBXU.vis_leaf_ok_svU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv STKF SCRP NF32 U2 TP0 W_OK CRS_OK WRS_OK IMG_OK
             G.CPS G.TAGS G.RETS K HKnil DEF0 V S2 W_ENC Vb ltac:(vm_compute; reflexivity) UV S2LT (kitx SPTX.FRZS2 E0 (CC.env_agree_refl _ _)) ltac:(vm_compute; reflexivity)
             VSTR (EvStr 3 (PML.ps_buf ps)) (PML.ps_buf ps) (fun R0 => PML.a2 R0 3) (fun _ => kx + PML.kleft ps * hl_k_per_malloc L) (fun _ => bxu + PMX.pbytes L ps)
             i c k ps1 j cj ci g1 M0c (VSTRING 3 (PML.ps_buf ps) ltac:(lia)) OBE OKV0 IL Hret Hcj Hpc Hchk
             (vis_site_str g1 M0c i c k ps1 cj ci IL Hendi Hvri HBLi H11 H12 HK1 HK2 Hcsp)
             (vis_ret (EvStr 3 (PML.ps_buf ps)) i c ps1 ci j g1 (or_intror (or_introl eq_refl)) Hc Hendi Hvri HBLi Hvrj Hendj HBLj)).
Qed.

