  - intros g1 i c k ps1 j s IL. exfalso. pose proof (CH2.leaves_all_sound _ _ _ leaf_ok _ _ _ _ _ IL) as Q. unfold leaf_chk in Q. cbv beta zeta iota in Q. discriminate Q.
  - intros g1 M0c OKV0 i c k ps1 j s IL. exfalso. pose proof (CH2.leaves_all_sound _ _ _ leaf_ok _ _ _ _ _ IL) as Q. unfold leaf_chk in Q. cbv beta zeta iota in Q. discriminate Q.
  - intros i c k ps1 pc IL g1 M0c OKV0. exact (leaves g1 M0c OKV0 i c k ps1 pc IL).
  - reflexivity.
  - rewrite LS. exact At0.
  - assert (Hden0 : CH2.den E0 (nth 0 G.BLS []) = PML.ps_blocks ps) by exact (kit SPT.den_BL0 E0 (CC.env_agree_refl _ _)).
    apply (CH2V.amb3V_intro L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv eg M 0%nat E0 M model (CH2V.okV_refl L M LBo sp G.HDECL W DEF0)).
    split.
    + split; [exact Hmo|]. split; [apply L5C.model_but_vm_refl|]. split; [apply CC.env_agree_refl|].
      split; [|split; [reflexivity | intros a _ _ Hd; exact Hd]].
      exists cr. split; [unfold CH2.cur, CH2V.LBr; rewrite Hden0; exact HH|].
      apply (proj2 (cred_pc eg 0 E0 cr ps Hden0 (proj2 WFM))). rewrite <- Hbxu. exact HPC.
    + split; [unfold XIj; rewrite (proj1 end0), vret0, (proj1 (proj2 (proj2 end0))); cbn beta iota; split; [intros a _ _; reflexivity | intros HJ; exfalso; vm_compute in HJ; discriminate HJ]|].
      split; [exact (conj HINV HLIT) | unfold GF; rewrite (proj1 end0), vret0; reflexivity].
  - exact Hfp.
Qed.
End Main.

